const rtdal000513Source0002 = `box_chars <- function() {
  if (is_utf8_output()) {
    list(
      "h" = "\u2500", # horizontal
      "v" = "\u2502", # vertical
      "l" = "\u2514", # leaf
      "j" = "\u251C" # junction
    )
  } else {
    list(
      "h" = "-", # horizontal
      "v" = "|", # vertical
      "l" = "\\", # leaf
      "j" = "+" # junction
    )
  }
}`

