const rtdal000522Source0015 = `test_package_root <- function() {
  x <- tryCatch(
    rprojroot::find_package_root_file(),
    error = function(e) NULL
  )

  if (!is.null(x)) return(x)

  pkg <- testthat::testing_package()
  x <- tryCatch(
    rprojroot::find_package_root_file(
      path = file.path("..", "..", "00_pkg_src", pkg)
    ),
    error = function(e) NULL
  )

  if (!is.null(x)) return(x)

  stop("Cannot find package root")
}`

const rtdal000522Source0020 = `r_pty <- function(.envir = parent.frame()) {
  skip_on_cran()
  # TODO: why does this fail on the CI, in covr
  if (
    Sys.getenv("R_COVR") == "true" &&
      isTRUE(as.logical(Sys.getenv("CI")))
  ) {
    skip("fails on CI in covr")
  }
  if (!Sys.info()[["sysname"]] %in% c("Darwin", "Linux"))
    skip("Needs Linux or macOS")

  r <- file.path(R.home("bin"), "R")
  p <- processx::process$new(
    r,
    c("-q", "--slave", "--vanilla"),
    pty = TRUE,
    env = c("current", R_CLI_HIDE_CURSOR = "false", R_LIBS = .libPaths()[1])
  )

  defer(
    {
      close(p$get_input_connection())
      p$wait(1000)
      p$kill()
    },
    envir = .envir
  )

  p$poll_io(1000)
  p$read_output()
  p
}`

const rtdal000522Source0022 = `skip_if_no_srcrefs <- function() {
  if (!asNamespace("pkgload")$is_dev_package("cli") &&
      Sys.getenv("R_KEEP_PKG_SOURCE") != "yes")
  {
    skip("no srcrefs")
  }
}`

