const rtdal000538Source0001 = `test_that("is_string", {
  strings <- list("foo", "", "111", "1", "-", "NA")
  not_strings <- list(
    1,
    character(),
    NA_character_,
    NA,
    c("foo", NA),
    c("1", "2"),
    NULL
  )

  for (p in strings) {
    expect_true(is_string(p))
    expect_silent(stopifnot(is_string(p)))
  }

  for (n in not_strings) {
    expect_false(is_string(n))
    expect_snapshot(error = TRUE, stopifnot(is_string(n)))
  }
})`

