const rtdal000554Source0001 = `test_that_cli("format_error", {
  expect_snapshot(
    error = TRUE,
    local({
      n <- "boo"
      stop(format_error(c(
        "{.var n} must be a numeric vector",
        "x" = "You've supplied a {.cls {class(n)}} vector."
      )))
    })
  )

  expect_snapshot(
    error = TRUE,
    local({
      len <- 26
      idx <- 100
      stop(format_error(c(
        "Must index an existing element:",
        "i" = "There {?is/are} {len} element{?s}.",
        "x" = "You've tried to subset element {idx}."
      )))
    })
  )
})`

