const rtdal000555Source0001 = `test_that("glue quotes and comments", {
  expect_snapshot({
    cli_dl(
      c(
        "test_1" = "all good",
        "test_2" = "not #good"
      )
    )
    cli::cli_dl(c("test_3" = "no' good either"))
    cli::cli_dl(c("test_4" = "no\" good also"))
    cli::cli_text("{.url https://example.com/#section}")
    cli::cli_alert_success("Qapla'")
  })
})`

const rtdal000555Source0002 = `test_that("quotes, etc. within expressions are still OK", {
  expect_snapshot({
    cli::cli_text("{.url URL} {x <- 'foo'; nchar(x)}")
    cli::cli_text("{.url URL} {x <- \"foo\"; nchar(x)}")
    cli::cli_text("{.url URL} {1 + 1 # + 1} {1 + 1}")
  })
})`

const rtdal000555Source0003 = `test_that("{. } is always a style", {
  cmd <- paste0("{.", basename(tempfile()), " }")
  expect_silent(glue_cmd(cmd, .envir = environment()))
  .foo <- 100
  vals <- glue_cmd("{.foo }", .envir = environment())$values
  expect_false(any(grepl("^v[0-9]+$", names(vals))))
})`

const rtdal000555Source0004 = `test_that("{ } is parsed with literal = FALSE", {
  expect_snapshot(
    format_message("{.emph {'{foo {}'}}")
  )
})`

