const rtdal000559Source0001 = `withr::local_envvar(CLI_NO_BUILTIN_THEME = "true")`

const rtdal000559Source0002 = `withr::local_options(cli.theme = NULL, cli.user_theme = NULL)`

const rtdal000559Source0005 = `test_that_cli(configs = c("plain", "ansi"), "inline classes", {
  classes <- c(
    "emph",
    "strong",
    "code",
    "pkg",
    "fun",
    "arg",
    "key",
    "file",
    "path",
    "email",
    "url",
    "var",
    "envvar",
    "cls"
  )

  do <- function(class) {
    special_style <- structure(
      list(
        list(color = "cyan"),
        list(before = "<<<"),
        list(after = ">>>")
      ),
      names = c(
        paste0("span.", class),
        paste0("span.", class),
        paste0("span.", class)
      )
    )

    cli_div(theme = special_style)
    txt <- glue::glue("This is {.<class> it} really", .open = "<", .close = ">")
    cli_text(txt)
  }

  expect_snapshot(
    invisible(lapply(classes, do))
  )
})`

const rtdal000559Source0006 = `test_that("{{ and }} can be used for comments", {
  expect_snapshot(local({
    cli_text("Escaping {{ works")
    cli_text("Escaping }} works")
    cli_text("Escaping {{ and }} works")
    cli_text("Escaping {{{{ works")
    cli_text("Escaping }}}} works")
    cli_text("Escaping {{{{ and }} works")
    cli_text("Escaping {{{{ and }}}} works")
    cli_text("Escaping {{ and }}}} works")
  }))
})`

const rtdal000559Source0007 = `test_that("no glue substitution in expressions that evaluate to a string", {
  expect_snapshot(local({
    msg <- "Message with special characters like } { }} {{"
    cli_text("{msg}")
    cli_text("{.emph {msg}}")
  }))
})`

const rtdal000559Source0008 = `test_that("S3 class is used for styling", {
  expect_snapshot(local({
    cli_div(
      theme = list(
        div = list("class-map" = list("foo" = "bar")),
        ".bar" = list(before = "::")
      )
    )
    obj <- structure("yep", class = "foo")
    cli_text("This is {obj}.")
  }))
})`

