const rtdal000568Source0002 = `test_that("bracket highlighting", {
  # [](){}
  expect_equal(
    color_brackets(c("[", "]", "(", ")", "{", "}"), col_seq),
    c("1[", "1]", "1(", "1)", "1{", "1}")
  )

  # [({[({})]})]
  expect_equal(
    color_brackets(
      c(
        "[",
        "(",
        "{",
        "[",
        "(",
        "{",
        "}",
        ")",
        "]",
        "}",
        ")",
        "]"
      ),
      col_seq
    ),
    c(
      "1[",
      "2(",
      "3{",
      "1[",
      "2(",
      "3{",
      "3}",
      "2)",
      "1]",
      "3}",
      "2)",
      "1]"
    )
  )

  # [[ [] ]][[ ()() ]]
  expect_equal(
    color_brackets(
      c("[[", "[", "]", "]", "]", "[[", "(", ")", "(", ")", "]", "]"),
      col_seq
    ),
    c(
      "1[[",
      "2[",
      "2]",
      "1]",
      "1]",
      "1[[",
      "2(",
      "2)",
      "2(",
      "2)",
      "1]",
      "1]"
    )
  )
})`

