const rtdal000571Source0003 = "test_that(\"clic__find_var\", {\n  x <- 10\n  expect_equal(.Call(clic__find_var, environment(), as.symbol(\"x\")), 10)\n  # not inherit\n  env <- new.env(parent = environment())\n  expect_snapshot(error = TRUE, {\n    .Call(clic__find_var, env, as.symbol(\"x\"))\n  })\n  expect_snapshot(error = TRUE, {\n    .Call(clic__find_var, environment(), as.symbol(basename(tempfile())))\n  }, transform = function(x) sub(\"`file.*`\", \"`<tmpfile>`\", x))\n})"

const rtdal000571Source0004 = `test_that("unloading stops the thread", {
  # It is important to skip this on CRAN, because in ASAN we do not
  # kill the tick thread on unload, because it triggers an ASAN crash,
  # which is similar to https://github.com/google/sanitizers/issues/1152
  skip_on_cran()
  fun <- function() {
    before <- ps::ps_num_threads()
    library(cli)
    between <- ps::ps_num_threads()
    unloadNamespace("cli")
    after <- ps::ps_num_threads()
    list(before = before, between = between, after = after)
  }

  out <- callr::r(fun)
  expect_equal(out$between, out$before + 1L)
  expect_equal(out$after, out$between - 1L)
})`

