const rtdal000576Source0001 = `test_that("cli_progress_message", {
  withr::local_options(cli.dynamic = FALSE, cli.ansi = FALSE)
  fun <- function() {
    cli_progress_message("Simplest progress 'bar', {.fun fn} {2} two{?s}")
  }
  expect_snapshot(capture_cli_messages(fun()))
})`

const rtdal000576Source0002 = "test_that(\"cli_progress_message error\", {\n  # we need the env var as well, because the on.exit handler of the progress\n  # bar might run after the on.exit handler that removes the `cli.dynamic`\n  # option.\n  withr::local_envvar(R_CLI_DYNAMIC = \"false\")\n  fun <- function() {\n    suppressWarnings(testthat::local_reproducible_output())\n    options(cli.dynamic = FALSE, cli.ansi = FALSE)\n    cli::cli_progress_message(\"Simplest progress 'bar', {.fun fn} {2} two{?s}\")\n    stop(\"oopsie\")\n  }\n\n  outfile <- tempfile()\n  on.exit(unlink(outfile), add = TRUE)\n  expect_snapshot(error = TRUE, {\n    callr::r(fun, stdout = outfile, stderr = outfile)\n  })\n  expect_snapshot(readLines(outfile))\n\n  # we need the env var as well, because the on.exit handler of the progress\n  # bar might run after the on.exit handler that removes the `cli.dynamic`\n  # option.\n  withr::local_envvar(R_CLI_DYNAMIC = \"true\")\n  fun2 <- function() {\n    suppressWarnings(testthat::local_reproducible_output())\n    options(cli.dynamic = TRUE, cli.ansi = TRUE)\n    cli::cli_progress_message(\"Simplest progress 'bar', {.fun fn} {2} two{?s}\")\n    stop(\"oopsie\")\n  }\n\n  outfile <- tempfile()\n  on.exit(unlink(outfile), add = TRUE)\n  expect_snapshot(error = TRUE, {\n    callr::r(fun2, stdout = outfile, stderr = outfile)\n  })\n  out <- rawToChar(readBin(outfile, \"raw\", 1000))\n  expect_snapshot(win2unix(out))\n})"

const rtdal000576Source0005 = `test_that("cli_progress_step", {
  withr::local_options(cli.dynamic = TRUE, cli.ansi = TRUE)
  suppressWarnings(testthat::local_reproducible_output())
  fun <- function() {
    cli_progress_step("First step")
    cli_progress_step("Second step")
  }
  msgs <- fix_times(capture_cli_messages(fun()))
  expect_snapshot(msgs)
})`

const rtdal000576Source0006 = `test_that("cli_progress_step error", {
  if (getRversion() < "3.5.0") skip("Needs R 3.5.0")
  fun <- function() {
    options(
      cli.dynamic = FALSE,
      cli.ansi = FALSE,
      cli.unicode = FALSE,
      cli.width = 80,
      width = 80,
      cli.num_colors = 1
    )
    cli::cli_progress_step("First step")
    cli::cli_progress_step("Second step")
    stop("oopsie")
  }

  outfile <- tempfile()
  on.exit(unlink(outfile), add = TRUE)
  expect_snapshot(error = TRUE, {
    callr::r(fun, stdout = outfile, stderr = "2>&1")
  })
  out <- fix_times(rawToChar(readBin(outfile, "raw", 1000)))
  expect_snapshot(win2unix(out))
})`

