const rtdal000587Source0001 = `test_that("events are properly generated", {
  skip_on_cran()
  ## This needs callr >= 3.0.0.90001, which is not yet on CRAN
  if (packageVersion("callr") < "3.0.0.9001") skip("Need newer callr")

  do <- function() {
    options(cli.message_class = "callr_message")
    cli::cli_div()
    cli::cli_h1("title")
    cli::cli_text("text")
  }

  rs <- callr::r_session$new()
  on.exit(rs$kill(), add = TRUE)

  msgs <- list()
  handler <- function(msg) {
    msgs <<- c(msgs, list(msg))
    if (!is.null(findRestart("cli_message_handled"))) {
      invokeRestart("cli_message_handled")
    }
    if (!is.null(findRestart("callr_r_session_muffle"))) {
      invokeRestart("callr_r_session_muffle")
    }
  }

  withCallingHandlers(
    rs$run(do),
    cli_message = handler
  )

  expect_equal(length(msgs), 4)
  lapply(msgs, expect_s3_class, "cli_message")
  expect_equal(msgs[[1]]$type, "div")
  expect_equal(msgs[[2]]$type, "h1")
  expect_equal(msgs[[3]]$type, "text")
  expect_equal(msgs[[4]]$type, "end")

  rs$close()
})`

const rtdal000587Source0002 = `test_that("subprocess with default handler", {
  skip_on_cran()
  ## This needs callr >= 3.0.0.90001, which is not yet on CRAN
  if (packageVersion("callr") < "3.0.0.9001") skip("Need newer callr")

  do <- function() {
    options(cli.message_class = "callr_message")
    cli::cli_div()
    cli::cli_h1("title")
    cli::cli_text("text")
  }

  rs <- callr::r_session$new()
  on.exit(rs$kill(), add = TRUE)

  msgs <- list()
  withr::with_options(
    list(
      cli.default_handler = function(msg) {
        msgs <<- c(msgs, list(msg))
        if (!is.null(findRestart("cli_message_handled"))) {
          invokeRestart("cli_message_handled")
        }
      }
    ),
    rs$run(do)
  )

  expect_equal(length(msgs), 4)
  lapply(msgs, expect_s3_class, "cli_message")
  expect_equal(msgs[[1]]$type, "div")
  expect_equal(msgs[[2]]$type, "h1")
  expect_equal(msgs[[3]]$type, "text")
  expect_equal(msgs[[4]]$type, "end")

  rs$close()
})`

const rtdal000587Source0003 = "test_that(\"output in child process\", {\n  skip_on_cran()\n  ## This needs callr >= 3.0.0.90001, which is not yet on CRAN\n  if (packageVersion(\"callr\") < \"3.0.0.9001\") skip(\"Need newer callr\")\n\n  # We need to do our own condition handling, otherwise callr will\n  # handle `cli_message` and copy it to the main process.\n  # So on `cli_message` we just call the default handler, which will\n  # call `message()`, and on `message` we'll copy the formatted message\n  # to the main process.\n\n  do <- function() {\n    options(cli.num_colors = 256)\n    withCallingHandlers(\n      {\n        cli::start_app(theme = cli::simple_theme())\n        cli::cli_h1(\"Title\")\n        cli::cli_text(\"This is generated in the {.emph subprocess}.\")\n        \"foobar\"\n      },\n      cli_message = function(msg) {\n        withCallingHandlers(\n          {\n            cli:::cli_server_default(msg)\n            invokeRestart(\"cli_message_handled\")\n          },\n          message = function(mmsg) {\n            class(mmsg) <- c(\"callr_message\", \"message\", \"condition\")\n            signalCondition(mmsg)\n          }\n        )\n      }\n    )\n  }\n\n  rs <- callr::r_session$new()\n  on.exit(rs$kill(), add = TRUE)\n\n  # Store the formatted messages from callr\n  # We also need to muffle the default handler here\n\n  msgs <- list()\n  result <- withCallingHandlers(\n    rs$run_with_output(do),\n    callr_message = function(msg) {\n      msgs <<- c(msgs, list(msg))\n      if (!is.null(msg$muffle) && !is.null(findRestart(msg$muffle))) {\n        invokeRestart(msg$muffle)\n      }\n    }\n  )\n\n  expect_equal(result$stdout, \"\")\n  expect_equal(result$stderr, \"\")\n  expect_identical(result$result, \"foobar\")\n  expect_null(result$error)\n  str <- paste(vcapply(msgs, \"[[\", \"message\"), collapse = \"\")\n  expect_true(ansi_has_any(str))\n  expect_match(str, \"Title\")\n  expect_match(str, \"This is generated\")\n\n  rs$close()\n})"

const rtdal000587Source0004 = `test_that("substitution in child process", {
  skip_on_cran()
  do <- function() {
    options(cli.message_class = "callr_message")
    cli::cli_text("This is process {Sys.getpid()}.")
  }

  rs <- callr::r_session$new()
  on.exit(rs$kill(), add = TRUE)

  out <- capt0(rs$run(do))
  expect_match(out, glue::glue("This is process {rs$get_pid()}"))

  rs$close()
})`

