const rtdal000593Source0001 = `test_that_cli("tree", {
  data <- data.frame(
    stringsAsFactors = FALSE,
    package = c(
      "processx",
      "backports",
      "assertthat",
      "Matrix",
      "magrittr",
      "rprojroot",
      "clisymbols",
      "prettyunits",
      "withr",
      "desc",
      "igraph",
      "R6",
      "crayon",
      "debugme",
      "digest",
      "irlba",
      "rcmdcheck",
      "callr",
      "pkgconfig",
      "lattice"
    ),
    dependencies = I(list(
      c("assertthat", "crayon", "debugme", "R6"),
      character(0),
      character(0),
      "lattice",
      character(0),
      "backports",
      character(0),
      c("magrittr", "assertthat"),
      character(0),
      c("assertthat", "R6", "crayon", "rprojroot"),
      c("irlba", "magrittr", "Matrix", "pkgconfig"),
      character(0),
      character(0),
      "crayon",
      character(0),
      "Matrix",
      c(
        "callr",
        "clisymbols",
        "crayon",
        "desc",
        "digest",
        "prettyunits",
        "R6",
        "rprojroot",
        "withr"
      ),
      c("processx", "R6"),
      character(0),
      character(0)
    ))
  )

  expect_snapshot(tree(data))

  expect_snapshot(tree(data, root = "desc"))

  # multi-line labels
  data$label <- data$package
  data$label[3] <- "assertthat\nstill going\nthird row"
  data$label[13] <- col_red("crayon\nand some more")
  data$label[14] <- "debugme\nmore debug"

  expect_snapshot(tree(data, root = "callr"))

  # Check that trees with apparent circularity error nicely
  data <- data.frame(
    stringsAsFactors = FALSE,
    X = c("a", "b", "c", "d", "e", "f", "g", "h", "j"),
    Y = I(list(
      c("b", "e", "f"),
      c("d", "g"),
      character(0),
      c("a", "h"),
      character(0),
      character(0),
      character(0),
      c("j"),
      character(0)
    ))
  )

  expect_warning(tree(data), "Endless loop found in tree: a -> b -> d -> a")
})`

