const rtdal000610Source0003 = `upper.to.lower.tri.inds <- function(n)
{
    if((n2 <- as.integer(n - 2L)) < 0) stop("'n' must be >= 2")
    rep(1L + cumsum(0:n2), (n - 1):1) +
	unlist(lapply(0:n2, function(k) cumsum(k:n2)))
}`

