	// R|
	// R| 		update_reactive = function(pal_name, pal_nr) {
	// R| 			pal = pal_name
	// R| 			if (pal == "") {
	// R| 				tab_vals$pal = character(0)
	// R| 				tab_vals$pal_name = character(0)
	// R| 				tab_vals$n = integer(0)
	// R| 				tab_vals$palBW = character(0)
	// R| 				tab_vals$idA1 = integer(0)
	// R| 				tab_vals$idA2 = integer(0)
	// R| 				tab_vals$idB1 = integer(0)
	// R| 				tab_vals$idB2 = integer(0)
	// R| 				tab_vals$CR = numeric(0)
	// R| 				tab_vals$idC1 = integer(0)
	// R| 				tab_vals$idC2 = integer(0)
	// R| 				tab_vals$b = integer(0)
	// R| 				tab_vals$b = integer(0)
	// R| 				tab_vals$type = character(0)
	// R|
	// R| 			} else {
	// R| 				x = c4a_info(pal)
	// R|
	// R| 				if (tab_vals$n > x$nmax || tab_vals$n < x$nmin) return(NULL)
	// R|
	// R| 				cols = as.vector(c4a(x$fullname, n = tab_vals$n))
	// R| 				if (tab_vals$na) cols = c(cols, c4a_na(tab_vals$pal_name))
	// R|
	// R| 				colsBW = unique(c(cols, "#FFFFFF", "#000000"))
	// R|
	// R| 				tab_vals$pal = cols
	// R| 				tab_vals$pal_name = pal_name
	// R|
	// R| 				tab_vals$palBW = colsBW
	// R|
	// R| 				tab_vals$b = approx_blues(cols)
	// R| 				tab_vals$r = approx_reds(cols)
	// R|
	// R| 				if (pal_nr == 4) {
	// R| 					# select maximum floating colors
	// R| 					tab_vals$idC1 = which.max(tab_vals$b)
	// R| 					tab_vals$idC2 = which.max(tab_vals$r)
	// R| 				} else if (pal_nr == 1) {
	// R| 					tab_vals$idA1 = 1L
	// R| 					tab_vals$idA2 = 2L
	// R| 				} else {
	// R| 					tab_vals$idB1 = 1L
	// R| 					tab_vals$idB2 = 2L
	// R| 					tab_vals$CR = colorspace::contrast_ratio(cols[1], cols[2])
	// R|
	// R| 				}
	// R|
	// R| 				tab_vals$type = x$type
	// R| 			}
	// R| 			if (pal_nr != 1) shiny::updateSelectizeInput(session, "cbfPal", choices = tab_vals$pals_byname, selected = pal)
	// R| 			if (pal_nr != 2) shiny::updateSelectizeInput(session, "CLPal", choices = tab_vals$pals_byname, selected = pal)
	// R| 			if (pal_nr != 3) shiny::updateSelectizeInput(session, "namePal", choices = tab_vals$pals_byname, selected = pal)
	// R| 			if (pal_nr != 4) shiny::updateSelectizeInput(session, "contrastPal", choices = tab_vals$pals_byname, selected = pal)
	// R| 			if (pal_nr != 5) shiny::updateSelectizeInput(session, "floatPal", choices = tab_vals$pals_byname, selected = pal)
	// R| 			if (pal_nr != 6) shiny::updateSelectizeInput(session, "APPPal", choices = tab_vals$pals_byname, selected = pal)
	// R|
	// R| 		}
