	// R|
	// R| 		cbf_map = function(cols, cvd) {
	// R| 			if (!length(cols)) return(NULL)
	// R|
	// R| 			hcl = get_hcl_matrix(cols)
	// R|
	// R| 			cols_cvd = sim_cvd(cols, cvd)
	// R|
	// R| 			borders = ifelse(mean(hcl[,3]>=50), "#000000", "#FFFFFF")
	// R|
	// R| 			c4a_plot_map(col1 = cols_cvd[1], col2 = cols_cvd[2], borders = borders, lwd = 1, crop = TRUE, dark = input$dark)
	// R| 		}
	// R|
	// R| 		cbf_lines = function(cols, cvd) {
	// R| 			if (!length(cols)) return(NULL)
