	// R| 			hcl = get_hcl_matrix(cols)
	// R|
	// R| 			cols_cvd = sim_cvd(cols, cvd)
	// R| 			c4a_plot_lines(cols = c(cols_cvd[1], col2 = cols_cvd[2]), lwd = 3, asp = .9, dark = input$dark)
	// R| 		}
