	// R|
	// R| 		get_click_id = function(pal, x, y) {
	// R| 			n = length(pal)
	// R|
	// R| 			brks_x = seq(0.04, 0.76, length.out = n + 2)
	// R| 			brks_y = seq(0, 1, length.out = n + 2)
	// R|
	// R| 			x_id = as.integer(cut(x, breaks = brks_x)) - 1
	// R| 			y_id = n + 1 - as.integer(cut(y, breaks = brks_y))
	// R|
	// R| 			if (!is.na(x_id) && (x_id < 1 || x_id > n)) x_id = NA
	// R| 			if (!is.na(y_id) && (y_id < 1 || y_id > n)) y_id = NA
	// R|
	// R| 			list(x = x_id, y = y_id)
	// R| 		}
