	// R|
	// R| 			ids = get_click_id(pal, input$cbfSimi_click$x, input$cbfSimi_click$y)
	// R|
	// R| 			if (!is.na(ids$x)) tab_vals$idA2 = ids$x
	// R| 			if (!is.na(ids$y)) tab_vals$idA1 = ids$y
	// R| 		})
