const rtdal000683Source0001 = `c4a_plot = function(palette, ..., dark = FALSE, include.na = FALSE, hex = FALSE, include.cvd = FALSE, nrows = NA, ncols = NA) {
	args = list(...)

	nms = names(palette)

	if (length(palette) == 1L) {
		pal = do.call(c4a, c(list(palette = palette, verbose = FALSE), args))
		if (is.null(pal)) {
			pal = validate_colors(palette, name = "palette")
		} else {
			nms = NULL
			if (is.matrix(pal)) {
				ncols = ncol(pal)
				pal = t(pal)
			}
			if (include.na) pal = c(pal, c4a_na(palette))
		}
	} else {
		if (is.matrix(palette)) {
			ncols = ncol(palette)
			palette = t(palette)
		}
		pal = validate_colors(palette, name = "palette")
	}

	if (hex) {
		nms = unname(pal)
		names(pal) = nms
	}



	if (is.null(pal)) return(invisible(NULL))

	pal = as.vector(pal)
	if (!is.null(nms)) {
		names(pal) = nms
	}

	if (include.cvd) {
		invisible(plot_cvd(pal, dark = dark, include.na = include.na))
	} else {
		invisible(plot_palette(pal, dark = dark, include.na = include.na, nrows = nrows, ncols = ncols))
	}
}`

const rtdal000683Source0002 = `c4a_plot_cvd = function(...) {
	args = list(...)
	args$include.cvd = TRUE
	do.call(c4a_plot, args)
}`

