			runtime.SetLocal(env, "t.chol.Q1", runtime.MustCallIn(ctx, env, "chol", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "t.Q1"))))
			runtime.SetLocal(env, "t.ichol.Q1", runtime.MustCallIn(ctx, env, "forwardsolve", runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "t", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "t.chol.Q1")))), runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "diag", runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "nrow", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "t.Q1"))))))))
			runtime.SetLocal(env, "t.iQ1", runtime.MustCallIn(ctx, env, "crossprod", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "t.ichol.Q1")), runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "t.ichol.Q1"))))
