const rtdal000744Source0001 = `knitr::opts_chunk$set(
  collapse = TRUE,
  comment = "#>"
)`

const rtdal000744Source0009 = `generate_abc <- generator(function() {
  for (x in letters[1:3]) {
    yield(x)
  }
})`

const rtdal000744Source0016 = `generate_natural_numbers <- generator(function(from = 1L) {
  x <- from
  repeat {
    yield(x)
    x <- x + 1L
  }
})`

const rtdal000744Source0021 = `while (!is_exhausted(x <- abc())) {
  print(x)
}`

const rtdal000744Source0023 = `loop(for (x in abc) {
  print(x)
})`

const rtdal000744Source0029 = `adapt_toupper <- generator(function(i) {
  for (x in i) {
    yield(toupper(x))
  }
})`

const rtdal000744Source0036 = `ABC <- gen(for (x in abc) yield(toupper(x)))`

const rtdal000744Source0038 = `adapt_map <- generator(function(.i, .fn, ...) {
  for (x in .i) {
    yield(.fn(x, ...))
  }
})`

