const rtdal000752Source0013 = `return_call <- function(info) {
  if (is_null(info$async_ops)) {
    quote(return(exhausted()))
  } else {
    quote(return(as_promise(last_value())))
  }
}`

const rtdal000752Source0014 = `continue_state <- function(expr, counter, continue, last, return, info) {
  if (last && return) {
    return(return_state(expr, counter, info))
  }

  i <- counter()
  next_i <- continue(counter, last)

  block <- expr({
    !!expr
    !!continue_call(next_i, machine_depth(counter))
  })
  state <- new_state(block, NULL, tag = i)
  counter(inc = 1L)

  state
}`

const rtdal000752Source0015 = "yield_state <- function(expr,\n                        counter,\n                        continue,\n                        last,\n                        return,\n                        info,\n                        assign_var = NULL) {\n  if (is_string(info$type, \"async\")) {\n    abort(\"Can't use `yield()` within an async function.\")\n  }\n\n  if (is_string(info$type, \"async_generator\")) {\n    expr <- expr(.last_value <- as_promise(!!expr))\n  }\n\n  suspend_state(\n    expr,\n    counter = counter,\n    continue = continue,\n    last = last,\n    return = return,\n    info = info,\n    assign_var = assign_var\n  )\n}"

const rtdal000752Source0016 = `await_state <- function(expr,
                        counter,
                        continue,
                        last,
                        return,
                        info,
                        assign_var = NULL) {
  if (is_string(info$type, "generator")) {
    stop_non_async_generator("await")
  }

  expr <- expr(.last_value <- then(as_promise(!!expr), callback = .self))

  suspend_state(
    expr = expr,
    counter = counter,
    continue = continue,
    last = last,
    return = return,
    info = info,
    assign_var = assign_var
  )
}`

const rtdal000752Source0017 = "suspend_state <- function(expr,\n                          counter,\n                          continue,\n                          last,\n                          return,\n                          info,\n                          assign_var) {\n  assign <- !is_null(assign_var)\n\n  return_last <- last && return && !assign\n\n  # Hard-code `last` to `FALSE` because we add assign states\n  saved_last <- last\n  last <- FALSE\n\n  i <- counter()\n  next_i <- continue(counter, last)\n  depth <- machine_depth(counter)\n\n  block <- expr({\n    !!expr\n    state[[!!depth]] <- !!next_i\n    suspend()\n    return(last_value())\n  })\n  states <- new_state(block, NULL, tag = i)\n  counter(inc = 1L)\n\n  if (!assign && saved_last && return) {\n    default_value <- quote(exhausted())\n  } else {\n    default_value <- NULL\n  }\n  arg_expr <- expr(if (missing(arg)) !!default_value else arg)\n\n  if (assign) {\n    if (saved_last && return) {\n      assign_expr <- expr(.last_value <- user_env[[!!assign_var]] <- !!arg_expr)\n      assign_state <- return_state(assign_expr, counter, info)\n      node_list_poke_cdr(states, assign_state)\n    } else {\n      assign_block <- expr({\n        user_env[[!!assign_var]] <- !!arg_expr\n        !!continue_call(continue(counter, saved_last), machine_depth(counter))\n      })\n      assign_state <- new_state(assign_block, NULL, counter())\n      counter(inc = 1L)\n      node_list_poke_cdr(states, assign_state)\n    }\n  } else if (!last) {\n    # Insert state to force the reentering generator argument in the\n    # proper context. This is how generators can be cancelled and cleaned up.\n    force_block <- expr({\n      .last_value <- !!arg_expr\n      !!continue_call(continue(counter, saved_last && !return_last), machine_depth(counter))\n    })\n    force_state <- new_state(force_block, NULL, counter())\n    node_list_poke_cdr(states, force_state)\n    counter(inc = 1L)\n  }\n\n  if (return_last) {\n    last_state <- return_state(NULL, counter, info)\n    node_list_poke_cdr(states, last_state)\n  }\n\n  states\n}"

const rtdal000752Source0018 = `if_states <- function(preamble,
                      condition,
                      then_body,
                      else_body,
                      counter,
                      continue,
                      last,
                      return,
                      info) {
  i <- counter()
  i_then <- i + 1L
  i_else <- i_then + 1L

  depth <- machine_depth(counter)

  if_block <- expr({
    !!!preamble %&&% list(user_call(preamble))
    if (!!condition) {
      state[[!!depth]] <- !!i_then
    } else {
      state[[!!depth]] <- !!i_else
    }
    state[[!!(depth + 1L)]] <- 1L
  })
  states <- new_state(if_block, NULL, i)
  counter(inc = 1L)

  offset <- if (is_null(else_body)) 0L else 1L
  then_machine <- walk_branch_states(then_body, offset, counter, continue, last, return, info)
  then_state <- new_state(then_machine, NULL, i_then)
  states <- node_list_poke_cdr(states, then_state)
  counter(inc = 1L)

  if (!is_null(else_body)) {
    else_machine <- walk_branch_states(else_body, 0L, counter, continue, last, return, info)
    else_state <- new_state(else_machine, NULL, i_else)
    states <- node_list_poke_cdr(states, else_state)
    counter(inc = 1L)
  }

  if (last) {
    after_block <- block(continue_call(continue(counter, last), depth))
    after_state <- new_state(after_block, NULL, counter())
    states <- node_list_poke_cdr(states, after_state)
    counter(inc = 1L)
  }

  states
}`

const rtdal000752Source0019 = `loop_states <- function(preamble,
                        init,
                        body,
                        cleanup,
                        counter,
                        nested_counter,
                        nested_states,
                        continue,
                        last,
                        info) {
  states <- NULL
  i <- counter()
  next_i <- i + 1L
  depth <- machine_depth(counter)

  preamble_block <- expr({
    !!!preamble %&&% list(user_call(preamble))
    !!!init %&&% list(init)
    state[[!!depth]] <- !!next_i
    state[[!!(depth + 1L)]] <- 1L
  })

  preamble_state <- new_state(preamble_block, NULL, i)
  states <- node_list_poke_cdr(states, preamble_state)
  i <- counter(inc = 1L)
  next_i <- continue(counter, last)

  loop_depth <- depth + 1L
  nested_counter <- nested_counter %||% new_counter(loop_depth, loop_depth = loop_depth)

  nested_machine_block <- expr({
    !!walk_loop_states(body, nested_states, nested_counter, info = info)
    !!!cleanup %&&% list(cleanup)
    length(state) <- !!depth
    !!continue_call(next_i, depth)
  })
  nested_machine_state <- new_state(nested_machine_block, NULL, i)
  states <- node_list_poke_cdr(states, nested_machine_state)
  counter(inc = 1L)

  states
}`

const rtdal000752Source0021 = `for_states <- function(preamble,
                       var,
                       iterator,
                       body,
                       counter,
                       continue,
                       last,
                       info) {
  loop_depth <- machine_depth(counter) + 1L

  async <- is_call(iterator, "await_each", ns = c("", "coro"))
  if (async) {
    if (is_string(info$type, "generator")) {
      stop_non_async_generator("await_each")
    }
    iterator <- iterator[[2]]
  }

  init <- expr(
    iterators[[!!loop_depth]] <- as_iterator(!!user_call(iterator))
  )

  nested_counter <- new_loop_counter(counter)

  if (async) {
    await_block <- expr({
      iterator <- iterators[[!!loop_depth]]
      iterator()
    })
    nested_states <- await_state(await_block, nested_counter, continue, FALSE, FALSE, info)

    condition <- expr({
      if (is_exhausted(arg)) {
        FALSE
      } else {
        user_env[[!!as.character(var)]] <- arg
        TRUE
      }
    })
    condition_state <- condition_state(condition, nested_counter)
    nested_states <- node_list_poke_cdr(nested_states, condition_state)
  } else {
    condition <- expr({
      iterator <- iterators[[!!loop_depth]]
      if (is_exhausted(elt <- iterator())) {
        FALSE
      } else {
        user_env[[!!as.character(var)]] <- elt
        TRUE
      }
    })
    nested_states <- condition_state(condition, nested_counter)
  }

  cleanup <- expr({
    iter_close(iterators[[!!loop_depth]])
    iterators[[!!loop_depth]] <- NULL
  })

  loop_states(
    preamble = preamble,
    init = init,
    body = body,
    cleanup = cleanup,
    counter = counter,
    nested_counter = nested_counter,
    nested_states = nested_states,
    continue = continue,
    last = last,
    info = info
  )
}`

const rtdal000752Source0022 = `condition_state <- function(condition, counter) {
  i <- counter()
  next_i <- i + 1L
  loop_depth <- machine_depth(counter)

  block <- block(expr(
    if (!!condition) {
      state[[!!loop_depth]] <- !!next_i
    } else {
      !!break_call()
    }
  ))
  state <- new_state(block, NULL, i)
  counter(inc = 1L)

  state
}`

const rtdal000752Source0023 = `break_state <- function(preamble, counter, info) {
  loop_depth <- loop_depth(counter)

  if (loop_depth == machine_depth(counter)) {
    continue <- expr({
      !!break_call()
    })
  } else {
    continue <- expr({
      length(state) <- !!(loop_depth - 1L)
      !!break_call()
    })
  }

  block <- expr({
    !!!preamble %&&% list(user_call(preamble))
    !!!continue
  })
  state <- new_state(block, NULL, counter())
  counter(inc = 1L)

  state
}`

const rtdal000752Source0024 = `next_state <- function(preamble, counter, info) {
  loop_depth <- loop_depth(counter)

  if (loop_depth == machine_depth(counter)) {
    continue <- expr({
      state[[!!loop_depth]] <- 1L
    })
  } else {
    continue <- expr({
      length(state) <- !!loop_depth
      !!break_call()
    })
  }

  block <- expr({
    !!!preamble %&&% list(user_call(preamble))
    !!!continue
  })
  state <- new_state(block, NULL, counter())
  counter(inc = 1L)

  state
}`

const rtdal000752Source0025 = "try_catch_states <- function(preamble,\n                             expr,\n                             counter,\n                             continue,\n                             last,\n                             return,\n                             info,\n                             assign = FALSE) {\n  if (assign) {\n    var <- call_lhs(expr)\n    expr <- call_rhs(expr)\n  }\n\n  # Can't use `match.call()` because we don't have any environment to\n  # expand dots in, and because expanding dots without keeping track\n  # of environments is problematic.\n  i <- try_catch_arg(expr)\n  body <- expr[[i]]\n  handlers_exprs <- as.list(expr[-c(1, i)])\n\n  finally <- handlers_exprs$finally\n  if (!is_null(finally)) {\n    stop_unimplemented(\"`tryCatch(finally = )`\")\n  }\n\n  state_i <- counter()\n  depth <- machine_depth(counter)\n  try_catch_depth <- depth + 1L\n\n  # Handlers can't be evaluated until runtime. We store their expressions in a\n  # list. They are evaluated when the user enters the `tryCatch()` state.\n  handler_body <- expr({\n    !!!preamble %&&% list(user_call(preamble))\n    handlers[[!!try_catch_depth]] <- user(base::list(!!!handlers_exprs))\n    state[[!!depth]] <- !!(state_i + 1L)\n    state[[!!(depth + 1L)]] <- 1L\n  })\n  states <- new_state(handler_body, NULL, counter())\n  state_i <- counter(inc = 1L)\n\n  try_catch_machine_call <- function(states, depth, prev_depth, next_i) {\n    machine <- expr({\n      !!machine_call(states, depth, prev_depth, next_i)\n      last_value()\n    })\n    expr(with_try_catch(handlers[[!!depth]], !!machine))\n  }\n\n  machine <- walk_branch_states(\n    body,\n    offset = 0L,\n    counter = counter,\n    continue = continue,\n    last = !assign && last,\n    return = return,\n    info = info,\n    new_machine = try_catch_machine_call\n  )\n\n  if (assign) {\n    machine <- expr(user_env[[!!as_string(var)]] <- !!machine)\n  }\n\n  if (last && return) {\n    machine <- expr(.last_value <- !!machine)\n    machine_state <- return_state(machine, counter, info)\n  } else {\n    machine_block <- block(\n      machine,\n      continue_call(continue(counter, last), depth)\n    )\n    machine_state <- new_state(machine_block, NULL, state_i)\n    counter(inc = 1L)\n  }\n  node_list_poke_cdr(states, machine_state)\n\n  states\n}"

const rtdal000752Source0026 = `continue_call <- function(next_i, depth) {
  if (next_i) {
    expr(state[[!!depth]] <- !!next_i)
  } else {
    quote(break)
  }
}`

