const rtdal000754Source0003 = `reduce <- function(.x, .f, ..., .init) {
  reduce_impl(.x, .f, ..., .init = .init)
}`

const rtdal000754Source0004 = `reduce_impl <- function(.x, .f, ..., .init, .left = TRUE) {
  if (is.object(.x)) {
    .x <- as_iterator(.x)
  }
  if (is_closure(.x)) {
    return(iter_reduce_impl(.x, .f, ..., .left = .left))
  }

  result <- reduce_init(.x, .init, left = .left)
  idx <- reduce_index(.x, .init, left = .left)

  .f <- as_closure(.f)
  for (i in idx) {
    result <- .f(result, .x[[i]], ...)

    # Return early if we get a reduced result
    if (is_done_box(result)) {
      return(unbox(result))
    }
  }

  result
}`

const rtdal000754Source0005 = "reduce_init <- function(x, init, left = TRUE) {\n  if (missing(init)) {\n    if (is_empty(x)) {\n      abort(\"`.x` is empty, and no `.init` supplied\")\n    } else if (left) {\n      x[[1]]\n    } else {\n      x[[length(x)]]\n    }\n  } else {\n    init\n  }\n}"

const rtdal000754Source0006 = `reduce_index <- function(x, init, left = TRUE) {
  n <- length(x)

  if (missing(init)) {
    if (left) {
      seq2(2L, n)
    } else {
      rev(seq2(1L, n - 1L))
    }
  } else {
    if (left) {
      seq_len(n)
    } else {
      rev(seq_len(n))
    }
  }
}`

const rtdal000754Source0007 = `iter_reduce_impl <- function(.x, .f, ..., .init, .left = TRUE) {
  if (!.left) {
    abort("Can't right-reduce with an iterator.")
  }

  # TODO: How do we close transducers?
  defer(iter_close(.x))

  .f <- as_function(.f)

  out <- NULL

  while (!is_exhausted(new <- .x())) {
    out <- .f(out, new, ...)

    # Return early if we get a reduced result
    if (is_done_box(out)) {
      return(unbox(out))
    }
  }

  out
}`

const rtdal000754Source0009 = `on_load(async_reduce %<~% async(function(.x, .f, ...) {
  out <- NULL

  while (TRUE) {
    new <- await(.x())

    if (is_exhausted(new)) {
      break
    }

    out <- .f(out, new, ...)

    # Return early if we get a reduced result
    if (is_done_box(out)) {
      return(unbox(out))
    }
  }

  out
}))`

