const rtdal000755Source0002 = "iter_take <- function(n) {\n  force(n)\n\n  function(continue) {\n    # Forward `n` here to make it safe for mutation\n    orig_n <- n\n    curr_n <- n\n\n    function(out, new) {\n      if (missing(out)) {\n        return(continue())\n      }\n\n      if (missing(new)) {\n        # Check `out` only after it has been completely finalised\n        # because along_builder() does not expose intermediary\n        # results\n        out <- continue(out)\n        if (length(out) < orig_n) {\n          abort(sprintf(\n            \"Not enough elements for `take()` \\\\\n             (%s / %s elements)\",\n            length(out),\n            orig_n\n          ))\n        }\n\n        return(out)\n      }\n\n      curr_n <<- curr_n - 1L\n      out <- continue(out, new)\n\n      if (curr_n) {\n        out\n      } else {\n        as_box(out, \"rlang_box_done\")\n      }\n    }\n  }\n}"

const rtdal000755Source0003 = `iter_map <- function(.f, ...) {
  .f <- as_closure(.f)

  function(continue) {
    force(continue)

    function(out, new) {
      if (missing(out)) {
        return(continue())
      }
      if (missing(new)) {
        return(continue(out))
      }

      continue(out, .f(new, ...))
    }
  }
}`

