const rtdal000765Source0001 = `test_that("async functions construct a generator", {
  expect_snapshot0(async_body(function() "value"))
  expect_snapshot0(async_body(function() await("value")))
  expect_snapshot0(async_body(function() if (1) await("value") else "else"))
  expect_snapshot0(async_body(function() while (1) if (2) await("value")))
  expect_snapshot0(async_body(function() while (1) foo <- await("value")))
})`

const rtdal000765Source0002 = `test_that("async() takes anonymous functions", {
  fn <- function() await("value")
  expect_error(async(fn), "anonymous")
})`

const rtdal000765Source0003 = `test_that("await() can't be called directly or out of place", {
  expect_error(await(1), "called directly")

  f <- async(function() list(await(1)))
  expect_error(f(), "within function arguments")
})`

const rtdal000765Source0005 = `test_that("async functions inherit from environment", {
  fn <- local({
    foobar <- "value"
    async(function() foobar)
  })
  expect_equal(prom_value(fn()), "value")
})`

const rtdal000765Source0006 = `test_that("async functions wrap return and yielded values", {
  later::with_temp_loop({
    out <- async(function() "value")()
    expect_promise(out, "value", "fulfilled")

    out <- async(function() await("value"))()
    expect_promise(out, status = "pending")
  })
})`

const rtdal000765Source0007 = `test_that("await() yields", {
  out <- NULL
  fn <- async(function() {
    for (i in 1:3) {
      out <<- c(out, i)
      await(i)
    }
  })
  wait_for(fn())
  expect_equal(out, 1:3)
})`

const rtdal000765Source0008 = `test_that("async_generator() creates streams", {
  produced <- NULL
  new_stream <- async_generator(function(x) {
    for (elt in x) {
      await(async_sleep(0))
      produced <<- c(produced, elt)
      yield(elt)
    }
  })

  s <- new_stream(1:3)
  out <- wait_for(s())
  expect_equal(out, 1L)

  consumed <- NULL
  async_obs <- async(function(i) {
    while (TRUE) {
      x <- await(i())

      if (is_exhausted(x)) {
        return("done")
      }

      consumed <<- c(consumed, x)
    }
  })

  out <- wait_for(async_obs(s))
  expect_equal(out, "done")

  expect_equal(produced, 1:3)
  expect_equal(consumed, 2:3)
})`

const rtdal000765Source0009 = "test_that(\"can adapt async streams\", {\n  new_stream <- async_generator(function(x) for (elt in x) yield(elt))\n\n  consumed <- NULL\n  async_obs <- async(function(i) {\n    while (TRUE) {\n      x <- await(i())\n\n      if (is_exhausted(x)) {\n        return(\"done\")\n      }\n\n      consumed <<- c(consumed, x)\n    }\n  })\n\n  s1 <- new_stream(1:3)\n  s2 <- async_adapt(s1, iter_map(`*`, 3L))\n  wait_for(async_obs(s2))\n\n  expect_identical(consumed, 1:3 * 3L)\n})"

const rtdal000765Source0010 = `test_that("async() functions can take dots", {
  fn <- async(function(...) list(...))
  expect_equal(wait_for(fn(x = 1)), list(x = 1))
})`

const rtdal000765Source0011 = "test_that(\"async_collect() collects\", {\n  new_stream <- async_generator(function(x) for (elt in x) yield(elt))\n\n  s1 <- new_stream(1:5)\n  s2 <- async_adapt(s1, iter_map(`*`, 3))\n\n  out <- wait_for(async_collect(s2))\n  expect_equal(out, as.list(1:5 * 3))\n\n\n  s1 <- new_stream(1:5)\n  s2 <- async_adapt(s1, iter_map(`*`, 3))\n\n  out <- wait_for(async_collect(s2, n = 3))\n  expect_equal(out, as.list(1:3 * 3))\n})"

const rtdal000765Source0012 = `test_that("for loops support await_each()", {
  new_stream <- async_generator(function(x) for (elt in x) yield(elt))

  f <- async_generator(function(s) for (x in await_each(s)) yield(x * 2))
  out <- wait_for(async_collect(f(new_stream(1:3))))
  expect_equal(out, list(2, 4, 6))

  values <- NULL
  f <- async_generator(function(s1, s2) {
    for (x in await_each(s1)) {
      values <<- c(values, x)
      for (y in await_each(s2)) {
        values <<- c(values, y)
      }
    }
  })
  wait_for(async_collect(f(new_stream(1:3), new_stream(11:12))))
  expect_equal(values, c(1, 11, 12, 2, 3))

  expect_snapshot0(async_body(function(s1, s2) {
    for (x in await_each(s1)) {
      values <<- c(values, x)
      for (y in await_each(s2)) {
        values <<- c(values, y)
      }
    }
  }))
})`

const rtdal000765Source0013 = `test_that("Iterators are cleaned up from most nested to least nested", {
  called <- NULL

  g1 <- coro::async_generator(function() {
    on.exit(called <<- c(called, "g1"))
    yield(1)
    yield(2)
  })
  g2 <- coro::async_generator(function() {
    on.exit(called <<- c(called, "g2"))
    yield(1)
    yield(2)
  })

  h <- coro::async_generator(function() {
    on.exit(called <<- c(called, "h"))
    for (i in await_each(g1())) {
      for (j in await_each(g2())) {
        yield(c(i, j))
        stop("foo")
      }
    }
  })

  expect_error(
    wait_for(async_collect(h()))
  )
  expect_equal(called, c("g2", "g1", "h"))
})`

