const rtdal000766Source0001 = `test_that("can create non-yielding generator functions", {
  gen <- generator(function() "foo")
  expect_identical(collect(gen()), list())
})`

const rtdal000766Source0002 = "test_that(\"can yield `NULL` without terminating iteration\", {\n  gen <- gen(yield(NULL))\n  expect_null(gen())\n  expect_exhausted(gen())\n})"

const rtdal000766Source0003 = `test_that("short syntax and for loop support", {
  numbers <- 1:6
  odds <- gen(for (x in numbers) if (x %% 2 != 0) yield(x))
  squares <- gen(for (x in odds) yield(x^2))

  out <- dbl()
  loop(for (x in squares) {
    out <- c(out, x)
  })

  expect_identical(out, dbl(1, 9, 25))
})`

const rtdal000766Source0004 = `test_that("generator factories print nicely", {
  factory <- generator(function() yield(NULL))
  expect_snapshot(print(factory, reproducible = TRUE))
  expect_snapshot(print(factory, reproducible = TRUE, internals = TRUE))
})`

const rtdal000766Source0005 = `test_that("generator instances prints nicely", {
  factory <- generator(function() yield(NULL))
  instance <- factory()
  expect_snapshot(print(instance, reproducible = TRUE))
  expect_snapshot(print(instance, reproducible = TRUE, internals = TRUE))
})`

const rtdal000766Source0006 = `test_that("can send values to generators", {
  g <- generator(function(x) repeat x <- yield(x))
  expect_identical(g(1)(), 1)
  expect_identical(g(2)(), 2)
})`

const rtdal000766Source0007 = `test_that("state is refreshed", {
  g <- generator(function(x) {
    y <- yield(x)
    yield(x)
  })

  expect_identical(g(1)(), 1)
  expect_identical(g("foo")(), "foo")
})`

const rtdal000766Source0008 = `test_that("generator() takes anonymous functions", {
  fn <- function() NULL
  expect_error(generator(fn), "anonymous")
})`

const rtdal000766Source0009 = "test_that(\"generator functions inherit from `coro_generator`\", {\n  g <- generator(function() NULL)\n  expect_true(inherits(g, \"coro_generator\"))\n  expect_false(inherits(g(), \"coro_generator\"))\n})"

const rtdal000766Source0010 = `test_that("generator factories can take dots", {
  new_gen <- generator(function(...) yield(list(...)))
  gen1 <- new_gen(x = 1)
  gen2 <- new_gen(x = 2)

  expect_equal(gen1(), list(x = 1))
})`

const rtdal000766Source0011 = `test_that("generators can take missing arguments", {
  new_gen <- generator(function(arg) yield(missing(arg)))
  expect_true(new_gen()())
  expect_false(new_gen(1)())
})`

const rtdal000766Source0012 = `test_that("yield within if within for loops properly", {
  new_gen <- generator(function() {
    x <- 1:10
    for (elt in x) {
      if (elt < 5) {
        yield(elt)
      } else {
        return(100L)
      }
    }
  })
  expect_identical(collect(new_gen()), list(1L, 2L, 3L, 4L))
})`

const rtdal000766Source0013 = `test_that("unexpected exits disable generators", {
  g <- gen({
    invokeRestart("foo")
    yield("foo")
  })

  withRestarts(
    foo = function() NULL,
    g()
  )
  expect_error(g(), "disabled because of an unexpected exit")
})`

const rtdal000766Source0014 = `test_that("can use tryCatch()", {
  out <- collect(gen({
    x <- tryCatch(
      error = function(...) "handled", {
        stop("error")
        yield("yield")
      }
    )
    yield(x)
  }))
  expect_equal(out, list("handled"))

  out <- collect(gen({
    x <- tryCatch(
      error = function(...) "handled", {
        stop("error")
        yield("yield")
      }
    )
    yield(x)
    yield("value")
  }))
  expect_equal(out, list("handled", "value"))

  out <- collect(gen({
    if (TRUE) {
      x <- tryCatch(
        error = function(...) "handled", {
          repeat if (TRUE) stop("error")
          yield("yield")
        }
      )
    }
    yield(x)
    yield("value")
  }))
  expect_equal(out, list("handled", "value"))

  out <- gen(tryCatch({ stop("foo"); yield("value") }, error = function(...) "handled"))()
  expect_equal(out, exhausted())

  # Handlers are matched to the condition class
  expect_error(
    gen({
      tryCatch(
        foo = function(...) "handled", {
          stop("error")
          yield("yield")
        }
      )
      yield("value")
    })(),
    regexp = "error"
  )
})`

const rtdal000766Source0015 = `test_that("tryCatch(finally = ) is handled", {
  expect_error(
    gen({
      tryCatch(
        error = function(...) "handled", {
          stop("error")
          yield("yield")
        },
        finally = return("finally")
      )
      "value"
    })(),
    regexp = "not implemented"
  )
})`

const rtdal000766Source0016 = `test_that("can yield within tryCatch()", {
  g <- gen({
    x <- tryCatch(error = function(...) "handled", {
      yield("value")
      stop("error")
    })
    yield(x)
    yield("value")
  })
  expect_equal(g(), "value")
  expect_equal(g(), "handled")
})`

const rtdal000766Source0017 = `test_that("can assign tryCatch()", {
  g <- gen({
    value <- tryCatch(error = function(...) "handled", {
      yield("value")
      stop("error")
    })
    yield(value)
  })
  expect_equal(collect(g), list("value", "handled"))
})`

const rtdal000766Source0018 = `test_that("can't await() within a generator", {
  expect_error(generator(function() await(foo))(), "non-async")
  expect_error(generator(function() for (x in await_each(foo)) NULL)(), "non-async")
})`

const rtdal000766Source0019 = `test_that("reentering the generator forces argument in proper context", {
  g <- generator(function() {
    yield("value")
    "wrong"
  })()
  g()
  expect_error(g(stop("error")), "error")

  g <- generator(function() {
    x <- tryCatch(error = function(...) "handled", {
      yield("value")
      return("wrong")
    })
    yield(x)
  })()
  g()
  expect_equal(g(stop("error")), "handled")
})`

const rtdal000766Source0020 = `test_that("exit expressions are suspended and resumed", {
  unwound <- FALSE

  g <- generator(function() {
    on.exit(unwound <<- TRUE)
    yield(1)
    yield(2)
  })()

  expect_equal(g(), 1)
  expect_false(unwound)

  expect_equal(g(), 2)
  expect_false(unwound)

  expect_exhausted(g())
  expect_true(unwound)

  unwound <- FALSE
  expect_exhausted(g())
  expect_false(unwound)
})`

const rtdal000766Source0021 = `test_that("formals of generator factory do not mask private variables", {
  generate <- generator(function(fn = "arg", env = "arg") yield(c(fn, env)))
  expect_equal(
    generate()(),
    c("arg", "arg")
  )
})`

const rtdal000766Source0022 = "test_that(\"yield-assign returns default `NULL`\", {\n  g <- generator(function() {\n    x <- yield(\"foo\")\n    yield(x)\n  })()\n  expect_equal(collect(g), list(\"foo\", NULL))\n\n  g <- generator(function() {\n    x <- tryCatch(yield(\"foo\"))\n    yield(x)\n  })()\n  expect_equal(collect(g), list(\"foo\", NULL))\n})"

const rtdal000766Source0023 = "test_that(\"generators call as_iterator() method\", {\n  local_methods(\n    `as_iterator.coro_iterator` = function(x) {\n      x <- 0L\n      function() {\n        if (x < 3L) {\n          x <<- x + 1L\n          x\n        } else {\n          exhausted()\n        }\n      }\n    }\n  )\n\n  i <- structure(list(), class = \"coro_iterator\")\n\n  out <- NULL\n  loop(for (x in i) out <- c(out, x))\n\n  expect_equal(out, 1:3)\n})"

const rtdal000766Source0024 = "test_that(\"can yield-assign with `=` (#29)\", {\n  g <- generator(function() {\n    x = yield(\"foo\")\n    yield(x)\n  })\n  expect_equal(collect(g()), list(\"foo\", NULL))\n\n  i <- g()\n  i()\n  expect_equal(i(\"bar\"), \"bar\")\n})"

const rtdal000766Source0025 = `test_that("stepping into generators returns visibly (#46)", {
  generate_abc <- generator(function() {
    yield("a")
    yield("b")
    "c"
  })
  abc <- generate_abc()
  expect_visible(abc())
  expect_visible(abc())
  expect_visible(abc())
  expect_visible(abc())
})`

const rtdal000766Source0026 = `test_that("generators do not cause CMD check notes (#40)", {
  skip_on_cran()
  expect_silent(
    invisible(compiler::cmpfun(
      generator(function() NULL),
      options = list(suppressAll = FALSE)
    ))
  )
})`

const rtdal000766Source0027 = `test_that("on.exit is called when loop breaks early (#52)", {
  called <- NULL
  g <- coro::generator(function() {
    on.exit(called <<- TRUE)
    yield(1)
    yield(2)
  })

  called <- FALSE
  expect_error(
    coro::loop(for (i in g()) {
      stop("boom!")
    })
  )
  expect_true(called)

  called <- FALSE
  iter <- g()
  iter()
  expect_false(called)

  iter(close = TRUE)
  expect_true(called)

  # Only called once
  called <- FALSE
  iter()
  iter(close = TRUE)
  expect_false(called)
})`

const rtdal000766Source0028 = `test_that("for loops in generators close their iterators (#52)", {
  called <- NULL
  g <- coro::generator(function() {
    on.exit(called <<- TRUE)
    yield(1)
    yield(2)
  })
  h <- coro::generator(function() {
    for (i in g()) {
      yield(i)
      stop("foo")
    }
  })

  called <- FALSE
  expect_error(
    collect(h())
  )
  expect_true(called)

  called <- FALSE
  expect_error(loop(for (i in h()) {}))
  expect_true(called)
})`

const rtdal000766Source0029 = `test_that("for loops in generators close their iterators - break (#52)", {
  called <- NULL
  g <- coro::generator(function() {
    on.exit(called <<- TRUE)
    yield(1)
    yield(2)
  })
  h <- coro::generator(function() {
    for (i in g()) {
      yield(i)
      break
    }
  })

  called <- FALSE
  collect(h())
  expect_true(called)

  called <- FALSE
  loop(for (i in h()) {})
  expect_true(called)
})`

const rtdal000766Source0030 = `test_that("Iterators are cleaned up from most nested to least nested", {
  called <- NULL

  g1 <- coro::generator(function() {
    on.exit(called <<- c(called, "g1"))
    yield(1)
    yield(2)
  })
  g2 <- coro::generator(function() {
    on.exit(called <<- c(called, "g2"))
    yield(1)
    yield(2)
  })

  h <- coro::generator(function() {
    on.exit(called <<- c(called, "h"))
    for (i in g1()) {
      for (j in g2()) {
        yield(c(i, j))
        stop("foo")
      }
    }
  })

  expect_error(
    collect(h())
  )
  expect_equal(called, c("g2", "g1", "h"))
})`

const rtdal000766Source0031 = `test_that("disabled generators only clean up once", {
  called <- NULL
  g <- coro::generator(function() {
    on.exit(called <<- c(called, TRUE))
    yield(1)
    stop("foo")
  })()

  expect_equal(g(), 1)

  expect_error(g(), "foo")
  expect_equal(called, TRUE)

  expect_error(g(), "disabled because of an unexpected exit")
  expect_equal(called, TRUE)

  expect_equal(g(close = TRUE), exhausted())
  expect_equal(called, TRUE)

  expect_equal(g(), exhausted())
  expect_equal(called, TRUE)

  expect_equal(g(close = TRUE), exhausted())
  expect_equal(called, TRUE)
})`

const rtdal000766Source0032 = `test_that("generators only clean up once", {
  called <- NULL
  g <- coro::generator(function() {
    on.exit(called <<- c(called, TRUE))
    yield(1)
  })()

  expect_equal(g(), 1)
  expect_null(called)

  expect_equal(g(), exhausted())
  expect_equal(called, TRUE)

  expect_equal(g(close = TRUE), exhausted())
  expect_equal(called, TRUE)

  expect_equal(g(), exhausted())
  expect_equal(called, TRUE)

  expect_equal(g(close = TRUE), exhausted())
  expect_equal(called, TRUE)
})`

